import json
x=json.load(open('source.json'))
print(type(x).__name__)
if isinstance(x,dict):
 print(list(x))
 for k,v in x.items():
  if isinstance(v,list):print(k,len(v))
else:
 print('COUNT',len(x))
 for i,a in enumerate(x): print(i,a.keys(),a.get('number'),len(a.get('source_xml','')),len(a.get('source_notes_xml','') or ''))
PY"

